import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderSurface } from 'claude-code'
import type { ProofRun } from '../types'
import { MERGE_OPTIONS, lastLine, mergeQuestion, mergedText, recipient, teardownRun } from './actions'
import type { MergeTarget } from './actions'
import { COLUMNS, GAP, cellColor, cells, layout } from './band'
import { paneView } from './pane'
import type { PaneActions } from './pane'
import { CORRECT_MS, CORRECT_TIMEOUT_MS, PANE, PROOFS_POLL_MS, cellButton, cellColumns, parsedProofs } from './proofs'
import { POLL_MS, parsed } from './state'

// The engine lists the values a module reads and writes by scanning it: the atoms live in this file, as does every
// function handed `$`, which it follows into no import.
const band = atom({ plugin: 'run-band', key: 'band' } as const, null)
const busy = atom({ plugin: 'run-band', key: 'busy' } as const, [])
const proofs = atom({ plugin: 'run-band', key: 'proofs' } as const, null)
const selected = atom({ plugin: 'run-band', key: 'selected' } as const, null)
const scope = atom({ plugin: 'run-band', key: 'scope' } as const, 'all')
const seen = atom({ plugin: 'run-band', key: 'seen' } as const, {})

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    if (e.surface === null) return next(e)
    await $.command.register({ name: 'proofs', description: 'List the proof store\'s runs across repos' })
    await loadSeen($)
    $.clock.every(POLL_MS, () => void refresh($))
    $.clock.every(PROOFS_POLL_MS, () => void refreshProofs($))
    $.clock.every(CORRECT_MS, () => void correctProofs($, CORRECT_MS / 1000))
    await refresh($)
    await refreshProofs($)

    return next(e)
  })

  on('command.run', { command: 'proofs' }, async $ => {
    await openProofs($)

    return {}
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const shown = await read($, band)
    const cell = cellButton(await read($, proofs))
    const runs = shown === null ? [] : shown.runs
    const { Box, Button, Link, Text } = $.ui.resolve(e)
    const sizes = layout(runs, e.props.bodyColumns - cellColumns(cell))
    const columns = COLUMNS.filter(column => sizes.widths[column] > 0)
    const ownRow = runs.length === 0 || sizes.detail === 0
    const open = () => void openProofs($)
    const cellBox = (
      <Box key="cell" flexShrink={0} marginLeft={GAP}>
        {cell.primary
          ? <Button key="proofs" variant="primary" label={cell.label} onPress={open} />
          : <Button key="proofs" plain dimColor label={cell.label} onPress={open} />}
      </Box>
    )

    return (
      <Box flexDirection="column">
        {ownRow && <Box key="cell-row" flexDirection="row" justifyContent="flex-end">{cellBox}</Box>}
        {runs.map((row, index) => {
          const text = cells(row)
          const links = { issue: row.issueUrl, pr: row.prUrl } as Record<string, string | null>

          return (
            <Box key={`row:${row.manifest}`} flexDirection="row" height={1} overflow="hidden">
              {columns.map(column => (
                <Box key={`${column}:${row.manifest}`} width={sizes.widths[column]} flexShrink={0} marginRight={GAP}>
                  <Text color={cellColor(row, column)}>
                    {links[column] ? <Link href={links[column] as string}>{text[column]}</Link> : text[column]}
                  </Text>
                </Box>
              ))}
              <Box key={`detail:${row.manifest}`} width={sizes.detail} flexGrow={1}>
                <Text wrap="truncate-end" color={row.state === 'halted' ? 'red' : undefined}>{row.detail}</Text>
              </Box>
              {index === 0 && !ownRow && cellBox}
            </Box>
          )
        })}
        {shown !== null && shown.hidden > 0 && <Text dimColor>{`+${shown.hidden} more`}</Text>}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const shown = await read($, band)

    return paneView($.ui.resolve(e), {
      list: await read($, proofs),
      repo: shown === null ? null : shown.repo,
      scope: await read($, scope),
      selected: await read($, selected),
      seen: await read($, seen),
      columns: e.props.bodyColumns,
    }, paneActions($))
  })
}

/** Where the scripts are: RUN_BAND_SKILLS_DIR, else the links the session hook keeps in ~/.claude/skills. */
async function skills($: EngineInterface): Promise<string> {
  return (await $.env.get('RUN_BAND_SKILLS_DIR')) ?? `${await $.env.get('HOME')}/.claude/skills`
}

/**
 * Runs the reader and writes `band` only when what it read differs from what is stored: a run moved, or a minute
 * passed. Compared with the stored value, not a module variable, so a reload (which starts the module over) writes
 * nothing new either.
 */
async function refresh($: EngineInterface): Promise<void> {
  const argv = ['php', `${await skills($)}/pipeline/checks/statusline_cli.php`, '--json', await $.session.cwd()]
  const next = await $.process.run(argv).then(
    result => (result.exitCode === 0 ? parsed(result.stdout) : null),
    () => null,
  )
  if (JSON.stringify(next) === JSON.stringify(await read($, band))) return
  await update($, band, () => next)
}

/**
 * Opens the pane, asked (a command or a press), and reads the list at once, so it never draws one older than the
 * press; then corrects the statuses without waiting on it, and the pane redraws when that pass is done.
 */
async function openProofs($: EngineInterface): Promise<void> {
  const opened = await $.ui.open({ id: PANE, title: 'Proofs', focus: true })
  if (!opened.isPlaced) $.ui.toast(opened.reason)
  await refreshProofs($)
  // not awaited: a pass still running when the session or the module goes has nothing left to tell
  void correctProofs($, 0).catch(() => undefined)
}

/**
 * The store's prune pass, which corrects every run's status from `gh` (proof-store.md §Retention): the script skips it
 * while another runs or one completed within `olderThan` seconds. Its output and a rejection are ignored; the list and
 * the band are read again either way. Never on the 15-second poll: `list` stays read-only.
 */
async function correctProofs($: EngineInterface, olderThan: number): Promise<void> {
  const argv = ['php', `${await skills($)}/pipeline/checks/proof_cli.php`, 'prune', '--if-older-than', String(olderThan)]
  await $.process.run(argv, { timeoutMs: CORRECT_TIMEOUT_MS }).catch(() => null)
  await refreshProofs($)
  await refresh($)
}

/** Runs `proof_cli.php list` and writes `proofs` only when the list changed, as `refresh()` does for the band. */
async function refreshProofs($: EngineInterface): Promise<void> {
  const argv = ['php', `${await skills($)}/pipeline/checks/proof_cli.php`, 'list']
  const next = await $.process.run(argv).then(
    result => (result.exitCode === 0 ? parsedProofs(result.stdout) : null),
    () => null,
  )
  if (JSON.stringify(next) === JSON.stringify(await read($, proofs))) return
  await update($, proofs, () => next)
}

/** The seen numbers this pane stored (`seen:<key>`, one store key per run), so another session's marks are kept. */
async function loadSeen($: EngineInterface): Promise<void> {
  const keys = (await $.store.keys()).filter(key => key.startsWith('seen:'))
  const marks = await Promise.all(keys.map(async key => [key.slice('seen:'.length), Number(await $.store.get(key))] as const))
  await update($, seen, () => Object.fromEntries(marks))
}

/** What the pane's buttons do. Each closes over this `$`: the engine follows `$` into no import (PR #224). */
function paneActions($: EngineInterface): PaneActions {
  return {
    filter: () => void update($, scope, now => (now === 'all' ? 'here' : 'all')),
    select: run => void select($, run),
    openPage: run => void openPage($, run),
    openFiles: url => void $.process.run(['open', url]),
    copySummary: (summary, surface) => void copySummary($, summary, surface),
    merged: target => void merged($, target),
  }
}

/** Selects a run, or folds it when it was selected; either way it is seen now, in the pane and in the store. */
async function select($: EngineInterface, run: ProofRun): Promise<void> {
  await update($, selected, now => (now === run.key ? null : run.key))
  const number = run.seen
  if (number === null) return
  await update($, seen, marks => ({ ...marks, [run.key]: number }))
  await $.store.set(`seen:${run.key}`, number)
}

async function openPage($: EngineInterface, run: ProofRun): Promise<void> {
  await $.process.run(['php', `${await skills($)}/pipeline/checks/proof_cli.php`, 'open', run.page])
}

async function copySummary($: EngineInterface, summary: string, surface: RenderSurface): Promise<void> {
  const copied = await $.ui.copy({ text: summary, surface })
  $.ui.toast(copied.isCopied ? 'summary copied' : copied.reason)
}

/**
 * Merged for a ready run's PR (session.md §The run band), pressed on the pane's selected run: confirmed in a dialog
 * that lists what it affects, then its session is told, or with none running the teardown runs here. It acts on the
 * target the closure captured as drawn. One press per run at a time: a second while the first is in flight toasts.
 */
async function merged($: EngineInterface, target: MergeTarget): Promise<void> {
  if (!(await askConfirm($, target))) return
  if (!(await claim($, target.key))) {
    $.ui.toast('already running')
    return
  }
  try {
    await deliver($, target)
  } finally {
    await update($, busy, list => list.filter(key => key !== target.key))
    await refreshProofs($)
    await refresh($)
  }
}

/** True only for exactly `Confirm`: Cancel, text typed under Other and a dismissed dialog (a rejection) act on nothing. */
async function askConfirm($: EngineInterface, target: MergeTarget): Promise<boolean> {
  const answer = await $.ui.ask(mergeQuestion(target), { header: 'Merged', options: MERGE_OPTIONS }).catch(() => null)

  return answer === 'Confirm'
}

async function claim($: EngineInterface, key: string): Promise<boolean> {
  let claimed = false
  await update($, busy, list => {
    claimed = !list.includes(key)

    return claimed ? [...list, key] : list
  })

  return claimed
}

/** Delivered means queued, never done (`SessionSendResult`); not delivered says why before the fallback's own toast. */
async function deliver($: EngineInterface, target: MergeTarget): Promise<void> {
  const to = recipient(target, await $.session.id())
  if (to.kind === 'prompt') {
    await $.prompt.submit({ text: mergedText(target) })
    return
  }
  if (to.kind === 'session') {
    const sent = await $.session.send({ to: { sessionId: to.sessionId }, text: mergedText(target) })
    if (sent.isDelivered) {
      $.ui.toast(`${mergedText(target)}: sent to the run's session`)
      return
    }
    $.ui.toast(`not delivered: ${sent.reason}`)
  }
  await teardown($, target)
}

async function teardown($: EngineInterface, target: MergeTarget): Promise<void> {
  const run = teardownRun(await skills($), target, await $.session.cwd(), await $.session.id())
  if (run === null) {
    $.ui.toast('leave the worktree first')
    return
  }
  const stdout = await $.process.run(run.argv, run.init).then(
    result => result.stdout,
    (error: unknown) => `teardown: did not finish (${error instanceof Error ? error.message : String(error)})`,
  )
  $.ui.toast(lastLine(stdout))
}

