import type { ProcessRunInit } from 'claude-code'
import type { Lease, ProofRun } from '../types'

export const TEARDOWN_MS = 600_000

/** Merged's dialog: Cancel first, so the dialog's focus starts on it; Confirm is the plain button that acts. */
export const MERGE_OPTIONS = ['Cancel', 'Confirm'] as const

/** What Merged acts on: a ready run with its PR and worktree, as the pane drew it (spec Assumption 22). */
export type MergeTarget = {
  key: string
  pr: number
  worktree: string
  branch: string | null
  nameWithOwner: string | null
  lease: Lease | null
  primary: string | null
}

export type Recipient = { kind: 'session'; sessionId: string } | { kind: 'prompt' } | { kind: 'fallback' }

/** The run as a merge target; null for one Merged cannot act on: not ready, or without a PR or a worktree. */
export function mergeTarget(run: ProofRun): MergeTarget | null {
  if (run.status !== 'ready' || run.pr === null || run.worktree === null) return null

  return {
    key: run.key, pr: run.pr, worktree: run.worktree, branch: run.branch,
    nameWithOwner: run.nameWithOwner, lease: run.lease, primary: run.primary,
  }
}

export const mergedText = (target: MergeTarget): string => `PR #${target.pr} merged`

/** The dialog's question: what the press affects, then the question it asks (spec Assumption 21). */
export function mergeQuestion(target: MergeTarget): string {
  const branch = target.branch === null ? '' : ` and branch ${target.branch}`
  const repo = target.nameWithOwner === null ? '' : ` (${target.nameWithOwner})`

  return `Merged tears down worktree ${target.worktree}${branch} once teardown.py finds the PR merged. Is PR #${target.pr}${repo} merged on GitHub?`
}

/** Who Merged tells: the session in the run's lease, this session's own prompt when that is this one, else nobody. */
export function recipient(target: MergeTarget, self: string): Recipient {
  if (target.lease === null) return { kind: 'fallback' }

  return target.lease.session_id === self ? { kind: 'prompt' } : { kind: 'session', sessionId: target.lease.session_id }
}

/** What the merge watch would have started, from the primary checkout; null from inside the worktree it removes. */
export function teardownRun(skills: string, target: MergeTarget, cwd: string, self: string): { argv: string[]; init: ProcessRunInit } | null {
  if (cwd === target.worktree || cwd.startsWith(`${target.worktree}/`)) return null

  return {
    argv: [
      'python3', `${skills}/orchestrate/teardown.py`, target.worktree, String(target.pr),
      ...(target.nameWithOwner === null ? [] : ['--repo', target.nameWithOwner]),
    ],
    init: { cwd: target.primary ?? cwd, env: { CLAUDE_CODE_SESSION_ID: self }, timeoutMs: TEARDOWN_MS },
  }
}

export const lastLine = (stdout: string): string => stdout.trim().split('\n').at(-1) || 'teardown: no output'

