import type { Row, RunState } from '../types'

export const COLUMNS = ['glyph', 'issue', 'step', 'status', 'age', 'pr'] as const
export type Column = (typeof COLUMNS)[number]
export type Layout = { widths: Record<Column, number>; detail: number }

export const GAP = 2

const GLYPHS: Record<RunState, string> = { halted: '▲', ready: '✓', running: '●' }
const STATE_COLORS: Record<RunState, string | undefined> = { halted: 'red', ready: 'green', running: undefined }

// East Asian Wide and Fullwidth: Hangul Jamo, CJK, Hiragana, Katakana, Hangul syllables, fullwidth forms.
const WIDE = /[\u1100-\u115F\u2E80-\u303E\u3041-\u33FF\u3400-\u4DBF\u4E00-\u9FFF\uA000-\uA4CF\uAC00-\uD7A3\uF900-\uFAFF\uFE30-\uFE4F\uFF00-\uFF60\uFFE0-\uFFE6\u{20000}-\u{3FFFD}]|\p{Emoji_Presentation}/u
const ZERO_WIDTH = /[\p{M}\u200B-\u200D\uFEFF]/u

/** How many terminal cells `text` takes: a wide character two, a combining mark or a joiner none, the rest one. */
export function cellWidth(text: string): number {
  return [...text].reduce((sum, character) => sum + (ZERO_WIDTH.test(character) ? 0 : WIDE.test(character) ? 2 : 1), 0)
}

export function cells(row: Row): Record<Column, string> {
  return {
    glyph: GLYPHS[row.state],
    issue: row.issue === null ? row.branch : `#${row.issue}`,
    step: row.step,
    status: row.status,
    age: row.age,
    pr: row.pr === null ? '' : `PR#${row.pr}`,
  }
}

export function cellColor(row: Row, column: Column): string | undefined {
  if (column === 'age') return row.stale ? 'yellow' : undefined

  return column === 'glyph' || column === 'status' ? STATE_COLORS[row.state] : undefined
}

/** Every column as wide as its widest value among `rows`; the detail takes what is left. */
export function layout(rows: Row[], bodyColumns: number): Layout {
  const widest = (column: Column): number => Math.max(0, ...rows.map(row => cellWidth(cells(row)[column])))
  const widths = Object.fromEntries(COLUMNS.map(column => [column, widest(column)])) as Record<Column, number>
  const columns = COLUMNS.reduce((sum, column) => sum + (widths[column] > 0 ? widths[column] + GAP : 0), 0)

  return { widths, detail: Math.max(0, bodyColumns - columns) }
}

