import type { ElementTable, RenderElement, RenderSurface } from 'claude-code'
import type { ProofGroup, ProofList, ProofRun, ProofScope } from '../types'
import type { MergeTarget } from './actions'
import { cellWidth } from './band'
import { HOTKEY_MARK, card, mergedLine, segmentTexts } from './cards'
import { filterLabel, filtered, fit, heading, inGroup, isUnread, lineText, numbered } from './proofs'

export type PaneKit = Pick<ElementTable, 'Box' | 'Button' | 'Text'>

export type PaneModel = {
  list: ProofList | null
  repo: string | null
  scope: ProofScope
  selected: string | null
  seen: Record<string, number>
  columns: number
}

export type PaneActions = {
  filter: () => void
  select: (run: ProofRun) => void
  openPage: (run: ProofRun) => void
  openFiles: (url: string) => void
  copySummary: (summary: string, surface: RenderSurface) => void
  merged: (target: MergeTarget) => void
}

/** The /proofs pane's tree: NEEDS YOU with the filter in its header, RUNNING, MERGED. No decisions on `$`. */
export function paneView(kit: PaneKit, model: PaneModel, actions: PaneActions): RenderElement {
  const { Box, Text } = kit

  return (
    <Box flexDirection="column">
      {model.list === null
        ? <Text dimColor>The proof store could not be read.</Text>
        : sections(kit, model, actions, model.list)}
    </Box>
  )
}

function sections(kit: PaneKit, model: PaneModel, actions: PaneActions, list: ProofList): RenderElement[] {
  const { Text } = kit
  const runs = filtered(list, model.scope, model.repo)
  const cards = numbered(runs).map(each => ({ ...each, selected: model.selected === each.run.key, unread: isUnread(each.run, model.seen) }))
  const drawn = (group: ProofGroup): RenderElement[] =>
    cards.filter(each => each.run.group === group).map(each => card(kit, model.columns, actions, each))
  const needs = drawn('needs-you')
  const running = drawn('running')
  const merged = inGroup(runs, 'merged').map(run => mergedLine(kit, model.columns, actions, run, model.selected === run.key))

  return [
    needsHeader(kit, model, actions, needs.length),
    ...(needs.length === 0 ? [<Text dimColor>Nothing waiting on you.</Text>] : needs),
    ...section(kit, model.columns, 'RUNNING', running),
    ...section(kit, model.columns, 'MERGED, LAST 24H', merged),
  ]
}

/** NEEDS YOU's header, always drawn: its count, and at its right the filter, dim, while the band names a repo. */
function needsHeader(kit: PaneKit, model: PaneModel, actions: PaneActions, count: number): RenderElement {
  const { Box, Button } = kit
  const title = heading('NEEDS YOU', count)
  const room = model.columns - cellWidth(lineText(title)) - 1 - HOTKEY_MARK

  return (
    <Box flexDirection="row">
      {segmentTexts(kit, title, model.columns)}
      <Box flexGrow={1} minWidth={1} />
      {model.repo !== null && (
        <Button key="filter" plain dimColor hotkey="r" label={fit(filterLabel(model.scope, model.repo, model.columns), room)} onPress={actions.filter} />
      )}
    </Box>
  )
}

/** A section's header, counted by its rows, one empty line above it, and its rows; a section with no rows draws nothing. */
function section(kit: PaneKit, columns: number, name: string, rows: RenderElement[]): RenderElement[] {
  const { Box } = kit

  return rows.length === 0 ? [] : [<Box flexDirection="row" marginTop={1}>{segmentTexts(kit, heading(name, rows.length), columns)}</Box>, ...rows]
}

