import type { ProofGroup, ProofList, ProofRun, ProofScope, ProofStatus } from '../types'
import { GAP, cellWidth } from './band'

export const PANE = 'proofs'
export const PROOFS_POLL_MS = 15_000
/** How often a session runs the prune pass that corrects the statuses from GitHub; the stamp makes it once a machine. */
export const CORRECT_MS = 900_000
/** One `gh pr view` per run with a PR: the pass may take a while. */
export const CORRECT_TIMEOUT_MS = 120_000
/** The pane's width below which a card draws no border, only a gutter in its status colour. */
export const NARROW = 40

export type Numbered = { run: ProofRun; number: number }
export type Cell = { label: string; primary: boolean }
/** One run of text in one style; a line of several is drawn as sibling Texts, never nested (spec Assumption 8). */
export type Segment = { text: string; dim?: boolean; bold?: boolean; underline?: boolean; color?: string }

export const GLYPHS: Record<ProofStatus, string> = { halted: '▲', ready: '✓', running: '●', merged: '✓' }
const STATUS_COLORS: Record<ProofStatus, string | undefined> = { halted: 'red', ready: 'green', running: undefined, merged: undefined }

/** The list's JSON; null for output that is no JSON or holds no `runs` list. */
export function parsedProofs(stdout: string): ProofList | null {
  try {
    const list = JSON.parse(stdout) as ProofList

    return Array.isArray(list.runs) ? list : null
  } catch {
    return null
  }
}

/** Unread, as the index reads it: a run with a seen number this pane never stored, or stored lower. Merged never is. */
export function isUnread(run: ProofRun, seen: Record<string, number>): boolean {
  if (run.group === 'merged' || run.seen === null) return false
  const stored = seen[run.key]

  return stored === undefined || stored < run.seen
}

/** The runs the pane shows: every repo's, or with `here` those of the band's repo (all of them when it has none). */
export function filtered(list: ProofList, scope: ProofScope, repo: string | null): ProofRun[] {
  return scope === 'here' && repo !== null ? list.runs.filter(run => run.nameWithOwner === repo) : list.runs
}

export const inGroup = (runs: ProofRun[], group: ProofGroup): ProofRun[] => runs.filter(run => run.group === group)

/** `text` cut to `columns` terminal cells, an ellipsis in the last one: a Button's label does not wrap. */
export function fit(text: string, columns: number): string {
  if (cellWidth(text) <= columns) return text
  let kept = ''
  for (const character of text) {
    if (cellWidth(`${kept}${character}…`) > columns) break
    kept += character
  }

  return `${kept}…`
}

/** What a line of segments reads. */
export const lineText = (segments: Segment[]): string => segments.map(segment => segment.text).join('')

/**
 * Segments cut to `columns` cells as one line, as fit() cuts their joined text: the ellipsis ends the segment it falls
 * in, in that segment's style, and the segments after it are dropped (spec Assumption 11).
 */
export function fitSegments(segments: Segment[], columns: number): Segment[] {
  const whole = lineText(segments)
  if (cellWidth(whole) <= columns) return segments
  let left = fit(whole, columns).length - 1
  const kept: Segment[] = []
  for (const segment of segments) {
    if (left <= segment.text.length) return [...kept, { ...segment, text: `${segment.text.slice(0, left)}…` }]
    kept.push(segment)
    left -= segment.text.length
  }

  return kept
}

/** The selected run's first line: `#<issue>  <base> ← <branch>`, each part left out when absent. */
export function headLine(run: ProofRun): string {
  const branch = run.branch === null ? null : run.base === null ? run.branch : `${run.base} ← ${run.branch}`

  return [run.issue === null ? null : `#${run.issue}`, branch].filter(part => part !== null).join('  ')
}

/** A status's colour, the band's: halted red, ready green; running and merged none, drawn dim. */
export const statusColor = (status: ProofStatus): string | undefined => STATUS_COLORS[status]

/** The needs-you and running runs in drawing order, numbered from 1 for their title and hotkey; merged runs get none. */
export function numbered(runs: ProofRun[]): Numbered[] {
  return runs.filter(run => run.group !== 'merged').map((run, index) => ({ run, number: index + 1 }))
}

export const prLabel = (run: ProofRun): string => (run.pr === null ? 'no PR' : `PR #${run.pr}`)

/** The checks line up to its first comma or bracket: `214 passed, 0 failed` is `214 passed`. */
export const testsShort = (tests: string): string => tests.replace(/(,| \().*$/s, '')

const questionsShort = (count: number): string => `${count} question${count === 1 ? '' : 's'}`

/** A card's state at its right: a waiting run's status and how long it has waited, a running run's leg. */
export function cardState(run: ProofRun): string {
  if (run.group === 'running') return run.step ?? 'running'

  return [run.status, run.age].filter((part): part is string => part !== null).join(' ')
}

/** The card's state in its status colour; a running run's, which has none, dim. */
export function stateSegment(run: ProofRun): Segment {
  const color = statusColor(run.status)

  return color === undefined ? { text: cardState(run), dim: true } : { text: cardState(run), color }
}

/** A run's PR underlined, as a link reads; `no PR` dim, as it names none (spec Assumption 5). */
const prSegment = (run: ProofRun): Segment => (run.pr === null ? { text: 'no PR', dim: true } : { text: `PR #${run.pr}`, underline: true })

/** A card's second line: repo and PR, then a waiting run's questions, else its tests, or a running run's age; dim but the PR. */
export function cardDetail(run: ProofRun): Segment[] {
  const extra = cardExtra(run)

  return [{ text: `${run.repo} · `, dim: true }, prSegment(run), ...(extra === null ? [] : [{ text: ` · ${extra}`, dim: true }])]
}

function cardExtra(run: ProofRun): string | null {
  if (run.group === 'running') return run.age
  if (run.questions.count > 0) return questionsShort(run.questions.count)

  return run.tests === null ? null : testsShort(run.tests)
}

/** The narrow card's second line: repo and `#<pr>` dim, then the card's state in its status colour. */
export const gutterDetail = (run: ProofRun): Segment[] => [
  { text: `${run.repo} ${run.pr === null ? 'no PR' : `#${run.pr}`} · `, dim: true },
  stateSegment(run),
]

/** The expanded card's tests line: a leading `<n> passed` in the theme's success colour, the rest dim (spec Assumptions 6, 10). */
export function testsLine(tests: string): Segment[] {
  const label: Segment = { text: 'Tests  ', dim: true }
  const passed = testsShort(tests)
  if (!/^\d+ passed$/.test(passed)) return [label, { text: tests }]
  const rest = tests.slice(passed.length)

  return [label, { text: passed, color: 'success' }, ...(rest === '' ? [] : [{ text: rest, dim: true }])]
}

/** A section's header: its name bold and dim, its count dim (spec Assumption 7). */
export const heading = (name: string, count: number): Segment[] => [{ text: name, bold: true, dim: true }, { text: ` ${count}`, dim: true }]

/** A merged run's line: repo, PR and title. */
export const mergedLabel = (run: ProofRun): string => `${run.repo} · ${prLabel(run)}  ${run.title}`

/** The filter's label: every repo's runs or the band repo's, shorter in a narrow pane (spec Assumptions 13, 22). */
export function filterLabel(scope: ProofScope, repo: string, columns: number): string {
  if (columns < NARROW) return scope === 'all' ? 'all' : 'this repo'

  return scope === 'all' ? 'all repos' : `${repo} only`
}

/** The band's cell: a primary button counting the runs waiting on the owner in any repo, whatever the pane's filter; a plain `proofs` with none. */
export function cellButton(list: ProofList | null): Cell {
  const waiting = list === null ? 0 : inGroup(list.runs, 'needs-you').length

  return waiting > 0 ? { label: `${waiting} waiting on you`, primary: true } : { label: 'proofs', primary: false }
}

/** The cells the band's cell takes from every row: its label, `[ ` and ` ]` when primary, and the gap before it. */
export const cellColumns = (cell: Cell): number => cellWidth(cell.label) + (cell.primary ? 4 : 0) + GAP

