import type { RenderElement } from 'claude-code'
import type { ProofRun } from '../types'
import { mergeTarget } from './actions'
import { cellWidth } from './band'
import type { PaneActions, PaneKit } from './pane'
import { GLYPHS, NARROW, cardDetail, cardState, fit, fitSegments, gutterDetail, headLine, mergedLabel, stateSegment, statusColor, testsLine } from './proofs'
import type { Numbered, Segment } from './proofs'

/** The theme key under the selected card: the person's own prompt rows' background, legible text in every theme (spec §Approaches). */
export const CARD_SELECTED = 'userMessageBackground'
/** The theme key under any other card while the pointer is over it: between the pane's background and CARD_SELECTED. */
export const CARD_HOVER = 'composerSidebarBackground'
/** The cells a plain Button with a hotkey draws before its label: `1: `. */
export const HOTKEY_MARK = 3
/** A bordered card's border and padding: one cell each, on both sides. */
const FRAME = 4
/** The unread mark and the glyph before a card's title, each with its space: `• ▲ `. */
const MARKS = 4
/** The narrow card's gutter, `▌ `, and the unread mark after it. */
const GUTTER = 2
/** The wide card's second line starts under the title, four cells in (spec Assumption 12). */
const INDENT: Segment = { text: '    ', dim: true }
/** A merged line's mark, in the theme's merged colour, before its Button. */
const MERGED_MARK = '  ✓ '

export type Card = Numbered & { selected: boolean; unread: boolean }

/**
 * One needs-you or running run: a bordered card from NARROW columns on, two gutter lines below that. Its Box is
 * keyed, the hover scope; no Box inside it is (spec Assumption 19).
 */
export function card(kit: PaneKit, columns: number, actions: PaneActions, each: Card): RenderElement {
  return columns < NARROW ? gutterCard(kit, columns, actions, each) : borderedCard(kit, columns, actions, each)
}

/** A merged run: its mark in the merged colour and one dim line, no card, number or unread mark; a press shows its detail under it. */
export function mergedLine(kit: PaneKit, columns: number, actions: PaneActions, run: ProofRun, selected: boolean): RenderElement {
  const { Box, Button, Text } = kit

  return (
    <Box flexDirection="column">
      <Box flexDirection="row">
        <Text color="merged">{MERGED_MARK}</Text>
        <Button key={`run:${run.key}`} plain dimColor label={fit(mergedLabel(run), columns - cellWidth(MERGED_MARK))} onPress={() => actions.select(run)} />
      </Box>
      {selected && <Box paddingLeft={2}>{body(kit, columns - 2, actions, run)}</Box>}
    </Box>
  )
}

function borderedCard(kit: PaneKit, columns: number, actions: PaneActions, each: Card): RenderElement {
  const { Box, Text } = kit
  const { run, selected } = each
  const color = statusColor(run.status)
  const inner = columns - FRAME
  const state = cardState(run)

  return (
    <Box
      key={`card:${run.key}`} flexDirection="column" paddingX={1}
      borderStyle={selected ? 'bold' : 'round'} borderColor={color} borderDimColor={color === undefined}
      {...cardBackground(selected)}
    >
      <Box flexDirection="row">
        {segmentText(kit, unreadMark(each))}
        <Text color={color}>{`${GLYPHS[run.status]} `}</Text>
        {title(kit, actions, each, inner - MARKS - 1 - cellWidth(state))}
        <Box flexGrow={1} minWidth={1} />
        {segmentText(kit, stateSegment(run))}
      </Box>
      <Box flexDirection="row">{segmentTexts(kit, [INDENT, ...cardDetail(run)], inner)}</Box>
      {selected && body(kit, inner, actions, run)}
    </Box>
  )
}

function gutterCard(kit: PaneKit, columns: number, actions: PaneActions, each: Card): RenderElement {
  const { Box } = kit
  const { run, selected } = each
  const width = columns - GUTTER

  return (
    <Box
      key={`card:${run.key}`} flexDirection="column" marginBottom={1}
      {...cardBackground(selected)}
    >
      <Box flexDirection="row">
        {gutter(kit, run)}
        {segmentText(kit, unreadMark(each))}
        {title(kit, actions, each, width - GUTTER)}
      </Box>
      <Box flexDirection="row">
        {gutter(kit, run)}
        {segmentTexts(kit, gutterDetail(run), width)}
      </Box>
      {selected && <Box paddingLeft={GUTTER}>{body(kit, width, actions, run)}</Box>}
    </Box>
  )
}

/** The unread mark in the accent colour, or the two cells it takes. */
const unreadMark = (each: Card): Segment => (each.unread ? { text: '• ', color: 'claude' } : { text: '  ' })

/** A card's background: the selected card keeps its own under the pointer, any other lights (spec Assumption 2). */
const cardBackground = (selected: boolean) => ({
  backgroundColor: selected ? CARD_SELECTED : undefined,
  hover: { backgroundColor: selected ? CARD_SELECTED : CARD_HOVER },
})

function gutter(kit: PaneKit, run: ProofRun): RenderElement {
  const { Text } = kit
  const color = statusColor(run.status)

  return <Text color={color} dimColor={color === undefined}>{'▌ '}</Text>
}

/** One segment as its own Text: a line is sibling Texts in a row, never a Text nested in a Text (spec Assumption 8). */
export function segmentText(kit: PaneKit, segment: Segment): RenderElement {
  const { Text } = kit

  return <Text color={segment.color} dimColor={segment.dim} bold={segment.bold} underline={segment.underline}>{segment.text}</Text>
}

/** A line of segments cut to its columns as one, a Text each. */
export const segmentTexts = (kit: PaneKit, segments: Segment[], columns: number): RenderElement[] =>
  fitSegments(segments, columns).map(segment => segmentText(kit, segment))

/** The title, a plain Button that selects the card: hotkey n for the first nine (drawn `n: `), a dim `n: ` before it after. */
function title(kit: PaneKit, actions: PaneActions, { run, number }: Card, columns: number): RenderElement[] {
  const { Button, Text } = kit
  const select = () => actions.select(run)
  if (number > 9) {
    const mark = `${number}: `

    return [
      <Text dimColor>{mark}</Text>,
      <Button key={`run:${run.key}`} plain label={fit(run.title, columns - cellWidth(mark))} onPress={select} />,
    ]
  }

  return [<Button key={`run:${run.key}`} plain hotkey={String(number)} label={fit(run.title, columns - HOTKEY_MARK)} onPress={select} />]
}

/** The selected run in full, under its lines: what it is, why it halted, what it did, its questions and checks, its buttons. */
function body(kit: PaneKit, columns: number, actions: PaneActions, run: ProofRun): RenderElement {
  const { Box, Text } = kit
  const head = headLine(run)

  return (
    <Box flexDirection="column">
      <Box flexDirection="column" marginTop={1}>
        {head !== '' && <Text dimColor>{fit(head, columns)}</Text>}
        {run.worktree !== null && <Text dimColor>{fit(run.worktree, columns)}</Text>}
      </Box>
      {run.reason !== '' && <Box marginTop={1}><Text color="red" wrap="wrap">{`▲ ${run.reason}`}</Text></Box>}
      {run.summary !== null && <Box marginTop={1}><Text wrap="wrap">{run.summary}</Text></Box>}
      {run.questions.count > 0 && questions(kit, columns, run)}
      {run.tests !== null && <Box flexDirection="row" marginTop={1}>{segmentTexts(kit, testsLine(run.tests), columns)}</Box>}
      {buttons(kit, actions, run)}
    </Box>
  )
}

function questions(kit: PaneKit, columns: number, run: ProofRun): RenderElement {
  const { Box, Text } = kit
  const more = run.questions.count - run.questions.first.length

  return (
    <Box flexDirection="column" marginTop={1}>
      <Text bold>Open questions</Text>
      {run.questions.first.map((question, index) => (
        <Box flexDirection="row">{segmentTexts(kit, [{ text: `${index + 1}. `, dim: true }, { text: question }], columns)}</Box>
      ))}
      {more > 0 && <Text dimColor>{`+${more} more`}</Text>}
    </Box>
  )
}

/** Open page, Files changed, Copy summary and, on a ready run, Merged; no hotkeys (never Resume or Go to session). */
function buttons(kit: PaneKit, actions: PaneActions, run: ProofRun): RenderElement {
  const { Box, Button } = kit
  const { filesUrl, summary } = run
  const target = mergeTarget(run)

  return (
    <Box flexDirection="row" flexWrap="wrap" columnGap={1} marginTop={1}>
      <Button key={`page:${run.key}`} label="Open page" onPress={() => actions.openPage(run)} />
      {filesUrl !== null && <Button key={`files:${run.key}`} label="Files changed" onPress={() => actions.openFiles(filesUrl)} />}
      {summary !== null && (
        <Button key={`copy:${run.key}`} label="Copy summary" onPress={press => actions.copySummary(summary, press.surface)} />
      )}
      {target !== null && <Button key={`merged:${run.key}`} label="Merged" onPress={() => actions.merged(target)} />}
    </Box>
  )
}

